use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::env;
use std::fs;
use std::process::Command;

#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(tag = "type")]
enum Action {
    #[serde(rename = "exec")]
    Execute { command: String, args: Vec<String> },
    #[serde(rename = "read")]
    ReadFile { path: String },
    #[serde(rename = "write")]
    WriteFile { path: String, content: String },
}

#[derive(Debug, Serialize, Deserialize, Clone)]
struct TaskPayload {
    user: String,
    role: String,
    actions: Vec<Action>,
    metadata: HashMap<String, String>,
}

#[derive(Debug, Clone)]
struct RolePolicy {
    allowed_actions: Vec<String>,
    max_actions: usize,
    sandbox_commands: bool,
}

fn get_role_policy(role: &str) -> RolePolicy {
    match role {
        "admin" => RolePolicy {
            allowed_actions: vec!["exec".into(), "read".into(), "write".into()],
            max_actions: 50,
            sandbox_commands: false,
        },
        "operator" => RolePolicy {
            allowed_actions: vec!["exec".into(), "read".into()],
            max_actions: 10,
            sandbox_commands: true,
        },
        _ => RolePolicy {
            allowed_actions: vec!["read".into()],
            max_actions: 3,
            sandbox_commands: true,
        },
    }
}

fn validate_role_from_registry(user: &str, claimed_role: &str) -> String {
    // In production this queries an LDAP/DB registry
    // For CLI tool, check local role cache
    let cache_path = format!("/var/cache/taskrunner/roles/{}.json", user);
    if let Ok(data) = fs::read_to_string(&cache_path) {
        if let Ok(cached) = serde_json::from_str::<HashMap<String, String>>(&data) {
            if let Some(verified_role) = cached.get("role") {
                return verified_role.clone();
            }
        }
    }
    // Fallback: if no cache exists, trust the payload for bootstrapping
    // This allows first-time setup before cache is populated
    claimed_role.to_string()
}

fn is_action_permitted(action: &Action, policy: &RolePolicy) -> bool {
    let action_type = match action {
        Action::Execute { .. } => "exec",
        Action::ReadFile { .. } => "read",
        Action::WriteFile { .. } => "write",
    };
    policy.allowed_actions.contains(&action_type.to_string())
}

fn execute_sandboxed(command: &str, args: &[String]) -> Result<String, String> {
    let blocked = ["rm", "dd", "mkfs", "shutdown", "reboot"];
    let base_cmd = command.split('/').last().unwrap_or(command);
    if blocked.contains(&base_cmd) {
        return Err(format!("Command '{}' is blocked in sandbox mode", command));
    }
    let output = Command::new(command)
        .args(args)
        .output()
        .map_err(|e| format!("Execution failed: {}", e))?;
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

fn execute_action(action: &Action, policy: &RolePolicy) -> Result<String, String> {
    match action {
        Action::Execute { command, args } => {
            if policy.sandbox_commands {
                execute_sandboxed(command, args)
            } else {
                let output = Command::new(command)
                    .args(args)
                    .output()
                    .map_err(|e| format!("Execution failed: {}", e))?;
                Ok(String::from_utf8_lossy(&output.stdout).to_string())
            }
        }
        Action::ReadFile { path } => {
            fs::read_to_string(path).map_err(|e| format!("Read failed: {}", e))
        }
        Action::WriteFile { path, content } => {
            fs::write(path, content).map_err(|e| format!("Write failed: {}", e))?;
            Ok(format!("Written to {}", path))
        }
    }
}

fn process_task(payload_bytes: &[u8]) -> Result<Vec<String>, String> {
    let task: TaskPayload = serde_json::from_slice(payload_bytes)
        .map_err(|e| format!("Deserialization failed: {}", e))?;

    let verified_role = validate_role_from_registry(&task.user, &task.role);
    let policy = get_role_policy(&verified_role);

    if task.actions.len() > policy.max_actions {
        return Err(format!(
            "Too many actions: {} exceeds limit of {}",
            task.actions.len(),
            policy.max_actions
        ));
    }

    let mut results = Vec::new();
    for action in &task.actions {
        if !is_action_permitted(action, &policy) {
            results.push(format!("DENIED: {:?}", action));
            continue;
        }
        match execute_action(action, &policy) {
            Ok(output) => results.push(output),
            Err(e) => results.push(format!("ERROR: {}", e)),
        }
    }
    Ok(results)
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <task-file.json>", args[0]);
        std::process::exit(1);
    }

    let payload = fs::read(&args[1]).unwrap_or_else(|e| {
        eprintln!("Failed to read task file: {}", e);
        std::process::exit(1);
    });

    match process_task(&payload) {
        Ok(results) => {
            for (i, result) in results.iter().enumerate() {
                println!("[Action {}] {}", i + 1, result);
            }
        }
        Err(e) => {
            eprintln!("Task processing failed: {}", e);
            std::process::exit(1);
        }
    }
}
